 function lockView(){reading=null;readingOwner='';readingContext='';readingVersion=null;readingPacket=null;readingDirty=false;readingWarning='';catchup=null;capabilityEpochKey?.fill(0);capabilityEpochKey=undefined;pending=[];identity=null;verified=null;contents={};badEvents=[];for(const key of Object.values(keys))key.fill(0);keys={};requests=[];password='';confirmPassword='';panel='forum';createKind='';editing=null;title='';body='';description='';order=0;files=undefined;draftAttachments=[];draftId=crypto.randomUUID();preview=false;emojiPicker=false;search='';restoreArchive=null;restoreFile=undefined;forkVault=null;exclude='';resetBranch=false;showReplica=false;replica={};}
 let currentOperation=Promise.resolve();
