 async function refreshStatus(){status=await api('/api/status');branding=await api<Branding>('/api/branding');if(status.read_only&&!status.configured)setupMode='restore';if(status.genesis){const p=JSON.parse(status.genesis.body)[3];policy=p;}}
 async function unlockMetadata(){if(!portable||!identity)return;if(identity.access){try{await api('/api/metadata',{key:identity.access.metadata,community:vault?.community||''});await refreshStatus();return;}catch{}}
  let total=1;for(let source=0;source<total&&source<51;source++){const bootstrap=await api('/api/bootstrap',{source});total=bootstrap.sources;if(!bootstrap.grants.length)continue;let epochKey:Uint8Array<ArrayBuffer>|undefined;try{epochKey=await unwrapEpoch(identity,bootstrap.ephemeral,bootstrap.grants);const metadata=await metadataKey(epochKey);await api('/api/metadata',{key:metadata,community:vault?.community||''});identity.access={metadata};await refreshStatus();return;}catch{}finally{epochKey?.fill(0);}}

