 async function auth(){if(!identity)return;if(portable){try{await unlockMetadata();}catch{}}const challenge=await api('/api/challenge',{device:identity.device});await api('/api/login',{challenge:challenge.id,device:identity.device,signed:await c.signed(identity,challenge.body)});}
 async function load(){if(!identity)return;if(portable)await unlockMetadata();const who=identity;const me=await api('/api/me');if(identity!==who)return;if((!me.member||me.member.status!=='active')&&!capabilityEpochKey){verified=null;contents={};for(const key of Object.values(keys))key.fill(0);keys={};notice=me.member?.status==='revoked'?'This identity is revoked on this branch.':'Waiting for an administrator to approve membership and key access.';return;}
  const archive=await api<Archive>('/api/sync');const oldPin=portable?portablePin:JSON.parse(localStorage.getItem('nightbuoy-pin')||'null');const v=await verifyArchive(archive,oldPin||{community:vault?.community||publicPin,tip:vault?.checkpoint||''});if(vault?.community&&v.community!==vault.community)throw Error('This recovery identity belongs to a different community.');
  const nextKeys:Record<number,Uint8Array<ArrayBuffer>>={};for(const [epoch,grants] of Object.entries(v.view.grants)){if(grants[identity.device.id])nextKeys[Number(epoch)]=await c.openGrant(who,grants[who.device.id]);}
  if(capabilityEpochKey&&!nextKeys[v.view.epoch])nextKeys[v.view.epoch]=capabilityEpochKey.slice();
  const {contents:next,rejected}=await openContents(v.events,nextKeys);if(identity!==who){for(const key of Object.values(nextKeys))key.fill(0);return;}badEvents=rejected;
  for(const key of Object.values(keys))key.fill(0);keys=nextKeys;contents=next;verified=v;pin();const queued=portable?pending:await listPending(who.device.id,v.community);for(const item of queued)if(v.events.some(e=>e.hash===item.hash))await dropPending(item.hash);if(identity!==who)return;pending=queued.filter(item=>!v.events.some(e=>e.hash===item.hash));settings={...v.view.policy};replica=portable||verified.view.members[who.device.id]?.status==='active'?await api('/api/replication'):{copied:false,remote:true};
  if(!status.read_only&&v.view.members[identity.device.id]?.role==='administrator')requests=await api('/api/requests');else requests=[];
  await loadReading(v,who);if(identity!==who)return;readCurrentTopic();if(readingDirty)void saveReading();
 }
 async function login(){if(!vault)throw Error('Import your encrypted recovery file first.');identity=await c.unlock(vault,password);password='';await auth();await load();}
 async function makeIdentity(){const issue=passphraseIssue(password,confirmPassword);if(issue)throw Error(issue);identity=await c.generate();const v=await c.lock(identity,password,status.community||'');localVault(v);await auth();}
 function recovery(){if(!vault)return;c.download(`nightbuoy-${vault.device.id.slice(0,10)}-recovery.json`,JSON.stringify(vault,null,2));savedRecovery=true;notice='Encrypted recovery file downloaded. Keep it and your passphrase separate from the forum host.';}
 async function newMember(){await makeIdentity();await join();password='';confirmPassword='';recovery();if(!status.locked)await load();else notice='Share the signed request with an administrator. Once approved, sign in with this identity to unlock the forum.';}
 async function createCommunity(){if(creationIssue)throw Error(creationIssue);bootstrap=bootstrap.trim();if(portable)policy={...policy,identity:'key',portable:{version:1,primary:status.publisher}};if(status.consensus)policy={...policy,consensus:status.consensus};if(!identity)await makeIdentity();if(policy.identity==='forge')await api('/api/join',{device:identity!.device,signed:await c.signed(identity!,['nightbuoy-join',1,'',identity!.device])});const key=await c.newEpoch();if(portable){const discovery=await wrapEpochForMembers([identity!.device],key);policy={...policy,portable:{...policy.portable!,discovery:{ephemeral:discovery.ephemeral,wrapped:discovery.wrapped}}};}const genesis=await c.signed(identity!,['nightbuoy-genesis',1,identity!.device,policy,status.publisher,[await c.grant(identity!.device,1,key)]]);const community=await c.hash(genesis.body);localVault(await c.lock(identity!,password,community,community));recovery();await write('genesis',genesis);await connectionFile();if(portable){const connection=await api('/api/connection');localVault(await c.lock(Object.assign(identity!,{access:{metadata:(await prepareMetadata(identity!,'genesis',genesis,null,{})).metadata_key}}),password,community,'p:'+connection.checkpoint));recovery();}bootstrap='';password='';confirmPassword='';if(portable)portablePin=null;else localStorage.removeItem('nightbuoy-pin');await refreshStatus();await load();notice='Community created. Save your recovery file, then create your first board.';}
 async function readRecovery(f:File){if(f.size>30000)throw Error('Recovery file is too large.');const v=JSON.parse(await f.text());if(status.community&&v.community&&v.community!==status.community)throw Error('This recovery file belongs to a different community.');localVault(v);notice='Recovery file loaded. Enter its passphrase to sign in.';}
 async function readRestore(){if(!restoreFile)throw Error('Choose an encrypted community archive.');if(restoreFile.size>66*1024*1024)throw Error('Encrypted archive exceeds the pilot frame limit.');const bytes=new Uint8Array(await restoreFile.arrayBuffer());let archive:Archive;if(bytes[0]===2){const who=identity??(forkVault?await c.unlock(forkVault,password):null);if(!who)throw Error('Import your surviving identity and enter its passphrase to unlock this encrypted archive.');archive=await openOpaqueArchive(who,bytes);}else{archive=JSON.parse(new TextDecoder().decode(bytes));}const v=await verifyArchive(archive,{community:expected,tip:''});restoreArchive=archive;notice=`Verified ${v.events.length} encrypted records. Confirm the community fingerprint before restoring.`;}
 async function restore(){
  if(portable){
   if(!restoreArchive)await readRestore();if(!expected||!resetBranch||!forkVault)throw Error('Confirm the old fingerprint, choose a separate branch and import a surviving identity.');
   const archive=restoreArchive!,v=await verifyArchive(archive,{community:expected,tip:''}),survivor=await c.unlock(forkVault,password);if(v.view.members[survivor.device.id]?.status!=='active')throw Error('This identity was not active at the selected checkpoint.');identity=survivor;await auth();
   const excluded=exclude.split(',').map(s=>s.trim()).filter(Boolean),epoch=v.view.epoch+1,key=await c.newEpoch(),grants=[];
   for(const m of Object.values(v.view.members))if(m.status==='active'&&!excluded.includes(m.device.id))grants.push(await c.grant(m.device,epoch,key));
   const recoveryDiscovery=await wrapEpochForMembers(Object.values(v.view.members).filter(m=>m.status==='active'&&!excluded.includes(m.device.id)).map(m=>m.device),key);
   const signed=await c.signed(survivor,['nightbuoy-control',1,v.community,v.authority,survivor.device.id,[...c.random()].map(n=>n.toString(16).padStart(2,'0')).join(''),'reconstitute',{exclude:excluded,publisher:status.publisher,epoch,grants,content_version:1,portable:{version:1,primary:status.publisher},discovery:{ephemeral:recoveryDiscovery.ephemeral,wrapped:recoveryDiscovery.wrapped},...(archive.proof?{checkpoint_proof:archive.proof}:{})}]);
   const plan=await api('/api/recover-prepare',{kind:'control',signed,archive,...await prepareMetadata(survivor,'control',signed,v,{})});await api('/api/commit',{ticket:plan.ticket,header:await c.signed(survivor,plan.body)});
   const connection=await api('/api/connection');portablePin={community:v.community,tip:'p:'+connection.checkpoint};localVault(await c.lock(survivor,password,v.community,portablePin.tip));password='';recovery();await connectionFile();await refreshStatus();await load();notice='Separate branch created on the new backend. The original branch is preserved.';return;
  }
  if(!restoreArchive)await readRestore();if(!expected)throw Error('Enter the trusted community fingerprint from an invitation or independent source.');
  let archive=restoreArchive!;if(status.consensus&&!resetBranch)throw Error('Starting on a new validator network requires an explicit separate branch. Select the branch reset option.');
  if(resetBranch){
   if(!forkVault)throw Error('Import a surviving member’s encrypted recovery file.');
   const v=await verifyArchive(archive,{community:expected,tip:''});const survivor=await c.unlock(forkVault,password);
   if(v.view.members[survivor.device.id]?.status!=='active')throw Error('This identity was not active at the selected checkpoint. Select an earlier retained checkpoint.');
   const excluded=exclude.split(',').map(s=>s.trim()).filter(Boolean);const epoch=v.view.epoch+1,key=await c.newEpoch();const grants=[];
   for(const m of Object.values(v.view.members))if(m.status==='active'&&!excluded.includes(m.device.id))grants.push(await c.grant(m.device,epoch,key));
   const control=await c.signed(survivor,['nightbuoy-control',1,v.community,v.authority,survivor.device.id,[...c.random()].map(n=>n.toString(16).padStart(2,'0')).join(''),'reconstitute',{exclude:excluded,publisher:status.publisher,epoch,grants,consensus:status.consensus??undefined,checkpoint_proof:archive.proof}]);
   const branch=await c.hash(control.body);archive={...archive,proof:undefined,controls:[...archive.controls,control],order:[...archive.order,branch]};
   if(!status.consensus)await verifyArchive(archive);localVault(forkVault);identity=survivor;
