  else notice='Community restored. Import your recovery file and sign in. An administrator can approve this host for publishing.';
 }

 async function exportPending(items:Pending[]=pending){if(!identity||!verified)return;const frame=await sealPrivate(identity,verified.community,'pending',items);c.download('nightbuoy-pending.nbp',frame,'application/octet-stream');}
 async function importPending(f:File){if(!identity||!verified)return;const who=identity,v=verified;if(f.size>66*1024*1024+1)throw Error('Pending export too large.');const bytes=new Uint8Array(await f.arrayBuffer());const list=bytes[0]===3?await openPrivate(who,v.community,'pending',bytes):JSON.parse(new TextDecoder().decode(bytes));if(!Array.isArray(list)||list.length>100)throw Error('Invalid pending export.');const known=new Set(pending.map(p=>p.hash)),staged:Pending[]=[];for(const value of list){const p=await validatePending(who,v.community,value);if(!known.has(p.hash)){known.add(p.hash);staged.push(p);}}if(identity!==who||verified?.community!==v.community||verified?.branch!==v.branch)return;assertPendingCapacity([...pending,...staged]);if(!portable)for(const p of staged)await savePending(p);if(identity!==who||verified?.community!==v.community||verified?.branch!==v.branch)return;pending=[...pending,...staged];notice=`Imported ${staged.length} private pending submission(s).`;}
 async function dropPending(hash:string){if(portable)pending=pending.filter(p=>p.hash!==hash);else await removePending(hash);}
 async function write(kind:string,signed:c.Signed){if(!portable)return api(kind==='genesis'?'/api/setup':kind==='control'?'/api/control':'/api/events',signed,kind==='genesis'?{'x-bootstrap-token':bootstrap}:{});for(let attempt=0;attempt<3;attempt++){const metadata=await prepareMetadata(identity!,kind,signed,verified,keys);const plan=await api('/api/prepare',{kind,signed,...metadata});if(plan.accepted)return;try{await api('/api/commit',{ticket:plan.ticket,header:await c.signed(identity!,plan.body)});return;}catch(e){if(!(e instanceof ApiError)||e.status!==409||attempt===2)throw e;}}}
 async function shareAccess(){if(!identity||!verified)throw Error('Unlock your identity first.');const connection=await api('/api/connection');const value=accessKey(c.b64(keys[verified.view.epoch]),verified.community,connection.branch_pin,connection.checkpoint,connection.primary.namespace);c.download('nightbuoy-private-access-key.txt',value,'text/plain');notice='Private forum access key exported. Share only with intended members; never upload it to storage.';}
 async function connectionFile(){if(portable)c.download('nightbuoy-connection.json',JSON.stringify(await api('/api/connection'),null,2));}
 async function join(){const result=await api('/api/join',{device:identity!.device,signed:await c.signed(identity!,['nightbuoy-join',status.locked?2:1,status.locked?status.publisher:status.community,identity!.device])});if(portable){c.download('nightbuoy-membership-request.json',JSON.stringify(result.request));notice='Share this signed membership request with an administrator. Check approval after they grant access.';}}
 async function importRequest(f:File){if(f.size>30000)throw Error('Membership request too large.');await api('/api/request-import',JSON.parse(await f.text()));await load();}
 async function sendControl(op:string,data:unknown){if(!identity||!verified)throw Error('Unlock an authorized identity.');let payload:any=data;const fields:any[]=['nightbuoy-control',1,verified.community,verified.authority,identity.device.id,[...c.random()].map(n=>n.toString(16).padStart(2,'0')).join(''),op,payload];if(portable&&['admit','rotate','revoke','reconstitute'].includes(op)){const metadata=await prepareMetadata(identity,'control',{body:c.canonical(fields),signature:''},verified,keys,true);payload={...payload,discovery:{ephemeral:metadata.metadata_ephemeral,wrapped:metadata.metadata_wrapped}};fields[7]=payload;}const signed=await c.signed(identity,fields);await write('control',signed);await load();}

 async function publish(kind:string,parent:string,payload:Content,id:string=crypto.randomUUID(),previous=''){
  if(!identity||!verified)throw Error('Sign in first.');const epoch=verified.view.epoch,key=keys[epoch];if(!key)throw Error('Current key access is unavailable.');
  const event=await c.encryptEvent(identity,key,[1,verified.community,identity.device.id,verified.authority,epoch,kind,id,parent,previous,Date.now()],payload);
  const item:Pending={hash:await c.hash(event.body),owner:identity.device.id,community:verified.community,event,wrappedKey:(await c.grant(identity.device,epoch,key)).key,created:Date.now()};
  assertPendingCapacity([...pending,item]);
  if(portable)pending=[...pending,item];else{await savePending(item);pending=await listPending(item.owner,item.community);}
  try{await write('event',event);await dropPending(item.hash);await load();return true;}catch(e){if(e instanceof ApiError&&e.status===401){lockView();throw e;}notice='Encrypted submission saved as pending. It is not confirmed. Open Account to retry, review or export it.';error=e instanceof Error?e.message:String(e);return false;}
 }
 async function retryPending(item:Pending){await write('event',item.event);await dropPending(item.hash);await load();notice='Submission accepted and verified.';}
 async function reviewPending(item:Pending){if(!identity||!verified)throw Error('Unlock your identity first.');const a=JSON.parse(item.event.body);const key=await c.openGrant(identity,item.wrappedKey);const payload=validateContent({kind:a[5]} as Event,await c.decryptEvent(key,item.event));key.fill(0);const existing=objects.find(e=>e.id===a[6]);compose(a[5],existing||null);draftId=a[6];title=payload.title||'';body=payload.body||'';description=payload.description||'';order=payload.order||0;draftAttachments=payload.attachments||[];panel='forum';if(a[5]==='topic')go('/b/'+a[7]);else if(a[5]==='reply')go('/t/'+a[7]);createKind=a[5];editing=existing||null;notice='Review this recovered draft before publishing against current permissions.';}

 async function attached(){const list:NonNullable<Content['attachments']>=[];let total=0;for(const f of Array.from(files||[])){total+=f.size;if(total>3*1024*1024)throw Error('Attachments must total at most 3 MiB per post.');list.push({name:f.name,size:f.size,data:c.b64(await f.arrayBuffer())});}return list;}
 async function savePost(){const checkedParent=editing?.parent||(createKind==='board'?'':createKind==='topic'?boardId:topicId),parentError=verified?parentProblem(verified.events,verified.view.policy.content_version,createKind,checkedParent):undefined;if(parentError)throw Error(parentError+' Existing history is read-only; you may still remove your own posts.');const lockedTarget=editing?.kind==='topic'?editing.id:editing?.kind==='reply'?editing.parent:createKind==='reply'?topicId:'';if(lockedTarget&&verified?.view.locked_topics?.includes(lockedTarget)&&!moderator)throw Error('This thread is locked. Ask a moderator to unlock it before posting or editing.');if((createKind!=='reply'&&!title.trim())||title.length>240||body.length>100000)throw Error('Enter a title (up to 240 characters) and keep the message below 100,000 characters.');if(createKind!=='board'&&!body.trim())throw Error('Enter a message.');const payload:Content=createKind==='board'?{title:title.trim(),description,order}:{...(editing?contents[editing.hash]:{}),title:createKind==='topic'?title.trim():undefined,body,attachments:[...(draftAttachments.length?draftAttachments:editing?contents[editing.hash]?.attachments||[]:[]),...await attached()]};const kind=createKind;const parent=editing?.parent||(kind==='board'?'':kind==='topic'?boardId:topicId);const id=editing?.id||draftId;const accepted=await publish(kind,parent,payload,id,editing?.hash||'');createKind='';editing=null;title='';body='';description='';files=undefined;if(accepted)notice='Submission accepted and verified. Check replica status for independent archive copies.';if(kind==='topic')go('/t/'+id);}
 function compose(kind:string,e:Event|null=null){preview=false;emojiPicker=false;draftId=e?.id||crypto.randomUUID();draftAttachments=[];createKind=kind;editing=e;title=e?contents[e.hash].title||'':'';body=e?contents[e.hash].body||'':'';description=e?contents[e.hash].description||'':'';order=e?contents[e.hash].order||0:boards.length;files=undefined;}
 async function rekey(op:string,member?:string){if(!verified)throw Error('Load the community first.');const epoch=verified.view.epoch+1,key=await c.newEpoch();const grants=[];for(const m of Object.values(verified.view.members))if(m.status==='active'&&m.device.id!==member)grants.push(await c.grant(m.device,epoch,key));await sendControl(op,{epoch,grants,...(member?{member}:{})});}
 async function admit(device:c.Device){if(!verified)throw Error('Load the community first.');const oldBoards=boards.map(b=>({event:b,payload:contents[b.hash]}));const p=verified.view.policy;const grants=[];let epoch=verified.view.epoch;if(p.history){for(const [e,key] of Object.entries(keys))grants.push(await c.grant(device,Number(e),key));}else{epoch++;const key=await c.newEpoch();for(const m of Object.values(verified.view.members))if(m.status==='active')grants.push(await c.grant(m.device,epoch,key));grants.push(await c.grant(device,epoch,key));}await sendControl('admit',{device,grants,epoch});if(!p.history)for(const b of oldBoards)await publish('board','',b.payload,b.event.id,b.event.hash);notice='Membership and encrypted key access granted.';}
 async function remove(e:Event){if(!confirm('Hide this content? Encrypted replicas and past readers may retain prior revisions.'))return;await publish('delete',e.parent,{body:'Removed'},e.id,e.hash);}
 function canRemove(e:Event){const root=verified?.events.find(x=>x.id===e.id&&!x.previous);return e.kind==='board'?admin:moderator||root?.author===identity?.device.id;}
 function canEdit(e:Event){const topic=e.kind==='topic'?e.id:e.kind==='reply'?e.parent:'';return canRemove(e)&&(!verified||!parentProblem(verified.events,verified.view.policy.content_version,e.kind,e.parent))&&(!verified?.view.locked_topics?.includes(topic)||moderator);}
 function quote(e:Event){compose('reply');const source=contents[e.hash].body||'',excerpt=Array.from(source).slice(0,20000).join('');body=['> '+short(e.author)+' wrote:',...excerpt.split('\n').map(line=>'> '+line),...(excerpt.length<source.length?['> …']:[]),'',''].join('\n');tick().then(()=>messageEditor?.focus());}
 async function signOut(){if(portable&&(pending.length||readingDirty||readingPacket)&&!confirm('Unsaved private state exists in this tab. Export pending posts and reading state from Account before signing out. Discard it and sign out?'))return;lockView();await api('/api/logout',{});notice='Signed out. Your local recovery vault remains encrypted.';}
 async function disconnect(){if((pending.length||createKind||readingDirty||readingPacket)&&!confirm('Switch forums and discard unsaved drafts, pending posts and reading changes? Export private backups from Account first.'))return;await api('/api/disconnect',{});lockView();vault=null;portablePin=null;publicPin='';expected='';savedRecovery=false;policy={name:'NightBuoy community',skin:'nightbuoy',admission:'approval',history:true,identity:'key',content_version:1};settings={...policy};setupMode='create';go('/');await refreshStatus();notice='Disconnected. Enter a storage URL to open another forum.';}
 async function exportArchive(){if(!verified)return;if(portable){const {frame}=await api('/api/export');c.download('nightbuoy-encrypted-archive.nbx',c.un64(frame),'application/octet-stream');}else c.download(`nightbuoy-${verified.community.slice(0,12)}-${verified.tip.slice(0,12)}.json`,JSON.stringify(verified.archive));}
 async function importArchive(f:File){if(f.size>64*1024*1024)throw Error('Archive too large.');await api('/api/import',JSON.parse(await f.text()));await load();notice='Verified history caught up. Divergent chains are never merged.';}
 async function verifyForge(id:string){sessionStorage.setItem('nightbuoy-setup-policy',JSON.stringify(policy));location.assign('/auth/'+id+'?return_to='+encodeURIComponent(location.pathname));}
 onMount(()=>{setTheme(theme);let timer:ReturnType<typeof setInterval>;run(async()=>{await initializeSession();portable=sessionPortable;const stored=portable?null:localStorage.getItem('nightbuoy-vault');if(stored)vault=JSON.parse(stored);const draft=sessionStorage.getItem('nightbuoy-setup-policy');if(draft)policy=JSON.parse(draft);await refreshStatus();timer=setInterval(()=>{if(identity&&!busy)run(async()=>{await load();if(admin&&verified?.view.policy.admission==='automatic'){const pending=requests.find(r=>!verified!.view.members[r.device.id]&&(verified!.view.policy.identity!=='forge'||r.verified));if(pending)await admit(pending.device);}},true);},15000);});const pop=()=>{route=location.pathname;};window.addEventListener('popstate',pop);document.addEventListener('visibilitychange',readCurrentTopic);return()=>{clearInterval(timer);window.removeEventListener('popstate',pop);document.removeEventListener('visibilitychange',readCurrentTopic);};});
</script>

<svelte:head><title>{verified?.view.policy.name||'Community forum'} · {branding.name}</title><link rel="icon" href={branding.favicon||'/nightbuoy.svg'}/>{#if branding.css}<link rel="stylesheet" href={branding.css}/>{/if}</svelte:head>
<a class="skip" href="#main">Skip to content</a>
<header class="nav"><div class="nav-inner"><a class="brand" href={branding.home}>{#if branding.logo}<img src={branding.logo} width="32" height="32" alt=""/>{/if}<span>{branding.name}</span></a><nav aria-label="Primary">{#each branding.links as link}<a href={link.href}>{link.label}</a>{/each}<button class="navlink current" onclick={()=>{panel='forum';go('/');}}>Forum</button><label class="appearance-picker"><span class="sr-only">NightBuoy appearance</span><select aria-label="NightBuoy appearance" value={theme} onchange={e=>setTheme(e.currentTarget.value)}>{#each themes as option}<option value={option.id}>{option.name}</option>{/each}</select></label>{#if identity}<button class="navlink" onclick={()=>{panel=panel==='account'?'forum':'account';readCurrentTopic();}}>Account</button><button class="navlink" disabled={busy} onclick={()=>run(signOut)}>Sign out</button>{/if}{#if portable&&status?.connected}<button class="navlink" disabled={busy} onclick={()=>run(disconnect)}>Switch forum</button>{/if}</nav></div></header>

<main id="main" class="container" aria-busy={busy}>
 {#if error}<div class="alert error" role="alert">{error}</div>{/if}
 {#if notice}<div class="alert" role="status">{notice}</div>{/if}
 {#if busy}<div class="progress" role="status">Working securely…</div>{/if}
 {#if portable&&identity&&verified&&verified.view.members[identity.device.id]?.status==='active'}{#key identity.device.id+verified.community+verified.branch}<Presence {identity} {verified} epochKey={keys[verified.view.epoch]} canShare={!!status?.writable&&!status?.read_only} expired={()=>lockView()}/>{/key}{/if}
 {#if status?.configured}{#if status.branch&&status.branch!==status.community}<div class="alert">This deployment follows an explicitly reset branch. Branch fingerprint: <code>{status.branch}</code><button onclick={()=>{if(confirm('Trust this separate branch? It does not merge with your former branch. Verify its fingerprint independently.'))run(async()=>{if(portable)portablePin={community:status.community,tip:status.branch};else localStorage.setItem('nightbuoy-pin',JSON.stringify({community:status.community,tip:status.branch}));if(identity)await load();notice='Branch explicitly selected.';});}}>Choose this branch</button></div>{/if}{/if}
 {#if !status}<p>Loading the community…</p>
 {:else if status.mode==='portable'&&!status.connected}
 <PortableConnection connected={async (capability,capabilityPin)=>{capabilityEpochKey=capability;if(capabilityPin)portablePin=capabilityPin;await refreshStatus();if(capability&&status.configured&&!status.locked){identity=await c.generate();await auth();await refreshStatus();await load();notice='Read access unlocked. Your key grants reading; membership and provider permission are required for posting.';}}}/>
 {:else if !status.configured}
  <div class="page-heading"><p class="eyebrow">Welcome to NightBuoy</p><h1>Create or restore your community.</h1><p class="muted">A forum that belongs to its members. The website is an address; the signed history and encryption keys travel with you.</p></div>
  <div class="tabs">{#if !status.read_only}<button class:chosen={setupMode==='create'} onclick={()=>setupMode='create'}>Create community</button>{/if}<button class:chosen={setupMode==='restore'} onclick={()=>setupMode='restore'}>Join / restore community</button></div>
  <section class="card setup">{#if !portable}<label>Local setup token<input type="password" bind:value={bootstrap} autocomplete="off" placeholder="Paste the one-use token from your server"/></label><details class="setup-token-help"><summary>Where do I get the setup token?</summary><p>NightBuoy generates it automatically when the server starts for the first time. Run this in your local checkout:</p><code>npm run dev:token</code><p>For the operator Docker deployment, run on its server:</p><code>docker compose -f compose.production.yaml --env-file operator/deployment.env exec -T app cat /data/app/bootstrap-token</code><p>For a direct installation, read <strong>bootstrap-token</strong> inside NIGHTBUOY_DATA. The token can be used once. It prevents a visitor from taking over a new install.</p></details>{/if}
   {#if setupMode==='restore'}<h2>Restore from an independent copy</h2><p>Use a retained checkpoint to resume a branch. Divergent histories stay separate.</p><label>Trusted community fingerprint<input bind:value={expected} spellcheck="false" placeholder="64-character SHA-256 fingerprint"/></label><label>Encrypted community archive<input type="file" accept="application/octet-stream,application/json,.json,.nbx" onchange={(e)=>{restoreFile=e.currentTarget.files?.[0];restoreArchive=null;}}/></label><label class="check"><input type="checkbox" bind:checked={resetBranch} disabled={status.read_only}/> Start a separate branch using a surviving member identity</label>
   {#if resetBranch}<p class="alert">This explicitly resets administrator authority on a separate branch. All former administrators become ordinary members. Other branches keep their own history and permissions; they never merge with this branch.</p><label>Surviving member recovery file<input type="file" accept="application/json,.json" onchange={e=>runFile(e,async f=>{if(f.size>30000)throw Error('Invalid recovery file size.');forkVault=JSON.parse(await f.text());})}/></label><label>Recovery passphrase<input type="password" bind:value={password} autocomplete="current-password"/></label><label>Exclude identities from future access (full fingerprints, comma-separated)<textarea bind:value={exclude} rows="2"></textarea></label>{/if}
   <div class="actions"><button disabled={busy} onclick={()=>run(readRestore)}>Verify archive</button><button class="primary" disabled={busy||(!portable&&!bootstrap)||!expected} onclick={()=>run(restore)}>Restore community</button></div>
   {:else}
    <h2>Community and membership</h2><label>Community name<input bind:value={policy.name} maxlength="80"/></label><p class="hint">The community name, membership and discussions are encrypted in storage. Optional installation branding is separate public presentation.</p>
    <label>New member admission<select bind:value={policy.admission}><option value="approval">Administrator approval</option><option value="automatic">Automatic while an unlocked administrator is online</option></select></label>
    <label>Joining requirements<select bind:value={policy.identity}>{#if !portable}<option value="forge">Verify an approved forge account</option>{/if}<option value="key">Portable cryptographic identity only</option></select></label>
    <label class="check"><input type="checkbox" bind:checked={policy.history}/> New members may decrypt existing history</label><p class="hint">Otherwise new members receive future keys; existing board descriptions are republished for navigation. Revocation protects future messages, not copies already saved.</p>
    {#if policy.identity==='forge'}<h3>Verify the creator</h3>{#if status.providers.length===0}<p class="alert">Configure a real forge OAuth provider in the operator configuration before creating a forge-backed community.</p>{/if}{#each status.providers as p}<button onclick={()=>verifyForge(p.id)}>Verify with {p.label}</button>{/each}{/if}
    <h3>Protect your portable identity</h3><p>Your private keys are encrypted on this device. Neither this host nor the forge gets your passphrase. Keep the encrypted recovery file to sign in on another website.</p><label>Unique passphrase<input type="password" bind:value={password} autocomplete="new-password" minlength={MIN_PASSPHRASE_LENGTH} maxlength={MAX_PASSPHRASE_LENGTH} aria-describedby="setup-passphrase-help setup-create-status"/></label><p class="hint" id="setup-passphrase-help">At least 20 characters. Several unrelated words make a long passphrase easier to remember.</p><label>Repeat passphrase<input type="password" bind:value={confirmPassword} autocomplete="new-password" maxlength={MAX_PASSPHRASE_LENGTH} aria-describedby="setup-create-status"/></label><p class="hint" id="setup-create-status" aria-live="polite">{creationIssue||'Ready to create your community.'}</p><button class="primary" disabled={busy||!!creationIssue} onclick={()=>run(createCommunity)}>Create community & download recovery file</button>
   {/if}
  </section>
 {:else if !identity}
  <section class="welcome"><p class="eyebrow">Your community. Your keys.</p><h1>A place for the conversation.</h1><p>Sign in and unlock your keys to read, search, and join the discussion. Storage providers keep encrypted copies.</p></section>
  <div class="auth-grid"><section class="card"><h2>{vault?'Unlock your identity':'Already a member?'}</h2><p>Use your recovery file on any trusted deployment of this community.</p><input class="hidden" bind:this={selectedFile} type="file" accept="application/json,.json" onchange={(e)=>runFile(e,readRecovery)}/><button disabled={busy} onclick={()=>selectedFile.click()}>Import encrypted recovery file</button>{#if vault}<p class="hint">{short(vault.device.id)}</p><form onsubmit={(e)=>{e.preventDefault();run(login);}}><label>Passphrase<input type="password" bind:value={password} autocomplete="current-password"/></label><button class="primary" disabled={busy||!password}>Sign in & unlock</button></form>{/if}</section>
   <section class="card"><h2>New to the community?</h2><p>{policy.admission==='approval'?'An administrator approves membership and encrypted key access.':'An unlocked administrator grants encrypted key access to eligible new members.'}</p>{#if policy.identity==='forge'}{#each status.providers as p}<button onclick={()=>verifyForge(p.id)}>First, verify with {p.label}</button>{/each}{/if}<form onsubmit={(e)=>{e.preventDefault();run(newMember);}}><label>New unique passphrase<input type="password" bind:value={password} autocomplete="new-password" minlength={MIN_PASSPHRASE_LENGTH} maxlength={MAX_PASSPHRASE_LENGTH} aria-describedby="member-passphrase-help member-create-status"/></label><p class="hint" id="member-passphrase-help">At least 20 characters. Use a unique passphrase you can keep safe.</p><label>Repeat passphrase<input type="password" bind:value={confirmPassword} autocomplete="new-password" maxlength={MAX_PASSPHRASE_LENGTH} aria-describedby="member-create-status"/></label><p class="hint" id="member-create-status" aria-live="polite">{identityIssue||'Passphrases match.'}</p><button disabled={busy||!!identityIssue}>Create identity & request membership</button></form></section></div>
  <p class="fingerprint">Community fingerprint <code>{status.community}</code></p>
 {:else if !verified}
  <section class="card narrow"><h1>Membership and key access</h1><p>Signed in as {short(identity.device.id)}. An administrator must grant this identity permission and encrypted keys before you can read.</p>{#if policy.identity==='forge'}{#each status.providers as p}<button onclick={()=>verifyForge(p.id)}>Verify with {p.label}</button>{/each}{/if}<button disabled={busy} onclick={()=>run(async()=>{await join();await load();})}>Submit / refresh membership request</button><button onclick={recovery}>Download encrypted recovery file</button><button disabled={busy} onclick={()=>run(load)}>Check approval</button></section>
 {:else if panel==='account'}
  <div class="page-heading"><p class="eyebrow">Private community identity</p><h1>{short(identity.device.id)}</h1><p class="muted">{verified.view.members[identity.device.id]?.role}. Your forge username and profile are not displayed.</p></div>
  {#if portable}<section class="card" aria-label="Private reading state"><h2>Private reading state</h2><p>Watches and read positions are encrypted for your identity. Keep a private backup when using an independent forum copy.</p>{#if reading}<p>{activity?.totalUnread||0} unread posts · {reading.watched.length} watched topics</p><div class="actions"><button disabled={busy} onclick={()=>run(exportReading)}>Export private reading state</button><button disabled={busy||!readingDirty} onclick={()=>run(saveReading)}>Save reading state</button><button disabled={busy} onclick={()=>run(allRead)}>Mark all read</button></div>{/if}<label>Restore private reading state<input type="file" accept=".nbs" onchange={e=>runFile(e,importReading)}/></label><button disabled={busy} onclick={()=>run(reloadReading)}>Reload reading state</button>{#if readingWarning}<p class="alert">{readingWarning}</p>{/if}</section>{/if}
  {#if pending.length}<section class="card"><h2>Pending encrypted submissions</h2><p>{portable?'These encrypted submissions exist only in this tab’s memory. Export them before closing.':'These are not confirmed. They are stored encrypted in this browser. Private/Tor browser storage may disappear when the browser closes; export a copy if needed.'}</p><button onclick={()=>run(()=>exportPending())}>Export encrypted pending submissions</button>{#each pending as item}<div class="member-row"><code>{item.hash.slice(0,16)}</code><div class="actions"><button disabled={busy} onclick={()=>run(()=>exportPending([item]))}>Export this submission</button><button disabled={busy} onclick={()=>run(()=>retryPending(item))}>Retry</button><button disabled={busy} onclick={()=>run(()=>reviewPending(item))}>Review draft</button><button disabled={busy} onclick={()=>run(async()=>{await dropPending(item.hash);pending=pending.filter(p=>p.hash!==item.hash);})}>Discard local pending copy</button></div></div>{/each}</section>{/if}
  <section class="card"><h2>Recovery and independent copies</h2>{#if portable}<button onclick={()=>run(shareAccess)}>Export private forum access key</button>{/if}<label>Import encrypted pending submissions<input type="file" accept=".nbp,.json" onchange={e=>runFile(e,importPending)}/></label>{#if portable}<button onclick={()=>showReplica=!showReplica}>Add / update a private encrypted backup</button>{#if showReplica}<PortableConnection action="replica-copy" history={async()=>Promise.all(Object.values(keys).map(metadataKey))} connected={async()=>{showReplica=false;await load();await connectionFile();}}/>{/if}{/if}<div class="actions"><button onclick={recovery}>Download encrypted recovery file</button><button onclick={()=>run(connectionFile)} hidden={!portable}>Download forum connection file</button><button onclick={()=>run(exportArchive)}>Download encrypted community archive</button>{#if admin}<button disabled={busy} onclick={()=>run(async()=>{replica=await api('/api/replicate',{});})}>Sync independent backups now</button>{/if}</div><label>Passphrase to authenticate a fresh recovery checkpoint<input type="password" bind:value={password} autocomplete="current-password"/></label><button disabled={busy||password.length<20} onclick={()=>run(async()=>{await c.unlock(vault!,password);localVault(await c.lock(identity!,password,verified!.community,verified!.checkpoint));password='';recovery();})}>Update recovery checkpoint & download</button><p>Keep your passphrase and recovery file. A forge login cannot recreate lost private keys.</p><p class="fingerprint">Community <code>{verified.community}</code><br/>Current checkpoint <code>{verified.tip}</code></p><p class="alert">{portable?'Confirmed history is stored on your remote backend. This companion cache is disposable. Pending posts stay in memory: export them before closing.':replica.copied?'An independent destination confirmed the current archive.':'No independent copy of this exact tip has been confirmed.'}</p>{#if replica.error}<p class="error">{replica.error}</p>{/if}</section>
  {#if admin}
   <section class="card"><h2>Administrator setup and policies</h2>{#if !verified.view.policy.content_version}<p class="hint">Enable current moderation tools to add thread locking and prevent new posts under removed boards or topics. Existing signed history is retained.</p><button disabled={busy} onclick={()=>run(()=>sendControl('policy',{...verified!.view.policy,content_version:1}))}>Enable current moderation tools</button>{/if}<label>Community name<input bind:value={settings.name} maxlength="80"/></label><div class="columns"><label>Admission<select bind:value={settings.admission}><option value="approval">Administrator approval</option><option value="automatic">Automatic with online key steward</option></select></label><label>Identity requirement<select bind:value={settings.identity}>{#if !portable}<option value="forge">Approved forge at enrollment</option>{/if}<option value="key">Portable identity only</option></select></label></div><label class="check"><input type="checkbox" bind:checked={settings.history}/> Grant new members existing history</label><button disabled={busy} onclick={()=>run(()=>sendControl('policy',settings))}>Save signed policy</button></section>
   <section class="card"><h2>Member requests</h2>{#if portable}<label>Import signed membership request<input type="file" accept=".json" onchange={e=>runFile(e,importRequest)}/></label>{/if}<p>Granting access encrypts community keys to the new member. They never pass through this service in plaintext.</p>{#each requests.filter(r=>!verified!.view.members[r.device.id]) as r}<div class="member-row"><div><strong>{short(r.device.id)}</strong><br/><span class="muted">{r.verified?'Forge verified on this host':'Key identity'}</span></div><button disabled={busy||(settings.identity==='forge'&&!r.verified)} onclick={()=>run(()=>admit(r.device))}>Approve & grant keys</button></div>{:else}<p class="muted">No pending requests on this host.</p>{/each}</section>
   <section class="card"><h2>Members and shared administration</h2><p>Administrators are peers. The creator has no permanent owner privilege. Removing a member rotates future encryption keys.</p>{#each Object.values(verified.view.members) as m}<div class="member-row"><div><strong>{short(m.device.id)}</strong><br/><span class="muted">{m.role} · {m.status}</span></div>{#if m.status==='active'}<div class="actions"><select aria-label={`Role for ${short(m.device.id)}`} value={m.role} disabled={busy} onchange={(e)=>run(()=>sendControl('role',{member:m.device.id,role:e.currentTarget.value}))}><option value="member">Member</option><option value="moderator">Moderator</option><option value="administrator">Administrator</option></select><button class="danger" disabled={busy} onclick={()=>{if(confirm('Revoke this member and rotate future keys? Existing saved content cannot be erased.'))run(()=>rekey('revoke',m.device.id));}}>Revoke</button></div>{/if}</div>{/each}</section>
   {#if badEvents.length}<section class="card"><h2>Isolated content</h2><p>These signed records could not be decrypted or validated. The evidence remains in history.</p>{#each badEvents as item}<div class="member-row"><div><code>{item.event.hash.slice(0,16)}</code><p>{item.reason} Author: {short(item.event.author)}</p></div>{#if heads(verified.events,item.event.id).some(e=>e.hash===item.event.hash)}<button disabled={busy} onclick={()=>run(()=>remove(item.event))}>Remove invalid content</button>{/if}</div>{/each}</section>{/if}
   {#if !portable}<section class="card"><h2>Independent hosting</h2><p>Only publication keys are recorded in community history. Storage credentials, owner accounts and private routes stay with the operator.</p><label>Backend publication key<input bind:value={publisherCandidate} spellcheck="false"/></label><button disabled={busy||!publisherCandidate} onclick={()=>run(async()=>{await sendControl('publisher',{key:publisherCandidate.trim(),approved:true});publisherCandidate='';})}>Approve backend key</button>{#each verified.view.publishers as publisher}<div class="member-row"><code>{publisher}</code><button disabled={busy} onclick={()=>run(()=>sendControl('publisher',{key:publisher,approved:false}))}>Revoke backend key</button></div>{/each}{#if !verified.view.publishers.includes(status.publisher)}<p>This host is read-only until approved for publication.</p><button disabled={busy} onclick={()=>run(()=>sendControl('publisher',{key:status.publisher,approved:true}))}>Approve this host for signed member writes</button>{:else}<p>This host is approved for signed member writes.</p>{/if}<label>Catch up from encrypted archive<input type="file" accept="application/json,.json" onchange={(e)=>runFile(e,importArchive)}/></label><button disabled={busy} onclick={()=>run(()=>rekey('rotate'))}>Rotate future keys</button><p class="hint">Catching up accepts only a compatible chain prefix. A divergent branch requires an explicit reset on a separate deployment. Keep the previous archive.</p></section>{/if}
  {/if}
 {:else}
  {#if badEvents.length}<div class="alert">{badEvents.length} encrypted record(s) could not be opened and were isolated. Other discussions remain available.</div>{/if}<div class="forum-top"><div><p class="eyebrow">Community forum</p><h1>{selectedTopic?contents[selectedTopic.hash].title:selectedBoard?contents[selectedBoard.hash].title:verified.view.policy.name}</h1><p class="muted">{selectedBoard?contents[selectedBoard.hash].description:'Shared knowledge. Independent homes. One conversation.'}</p></div><div class="account-chip"><span class="avatar">{identity.device.id.slice(0,2)}</span><div>{short(identity.device.id)}<small>{verified.view.members[identity.device.id]?.role}</small></div></div></div>
  <div class="toolbar"><div class="breadcrumbs"><button class="text" onclick={()=>go('/')}>All boards</button>{#if selectedBoard}<span>/</span><button class="text" onclick={()=>go('/b/'+selectedBoard!.id)}>{contents[selectedBoard.hash].title}</button>{/if}{#if selectedTopic}<span>/</span><span>Topic</span>{/if}</div><label class="search"><span class="sr-only">Search decrypted discussions</span><input type="search" placeholder="Search this community…" bind:value={search}/></label></div>
  {#if status.read_only}<div class="alert">This is a private read-only copy. No administrator approval or registration is required. Use a publishing frontend to contribute.</div>{:else if !verified.view.publishers.includes(status.publisher)}<div class="alert">This frontend is read-only. An administrator can approve this host from Account.</div>{/if}
  {#if reading}<section class="card" aria-label="Private activity"><div class="actions"><strong>{activity?.totalUnread||0} unread posts</strong><button disabled={busy} onclick={()=>run(allRead)}>Mark all read</button></div>{#if catchup&&(catchup.topics+catchup.replies+catchup.mentions)>0}<p role="status">Since your last visit: {catchup.topics} new topics, {catchup.replies} replies ({catchup.watched} in watched topics), {catchup.mentions} mentions.</p><button class="text" onclick={()=>catchup=null}>Dismiss catch-up</button>{/if}{#if watchedTopics.length}<details><summary>Watched topics ({watchedTopics.length})</summary>{#each watchedTopics as topic}<button class="result" onclick={()=>go('/t/'+topic.id)}><strong>{contents[topic.hash].title}</strong><span>{activity?.unread[topic.id]||0} unread</span></button>{/each}</details>{/if}{#if readingWarning}<p class="alert">{readingWarning} Manage private backups in Account.</p>{/if}</section>{/if}
  {#if search.trim()}<section class="card"><h2>Search results</h2><p class="hint">Search stays on this device.</p>{#each results as e}<button class="result" onclick={()=>go('/t/'+(e.kind==='topic'?e.id:e.parent))}><strong>{contents[e.hash].title||'Reply'}</strong><span>{contents[e.hash].body?.slice(0,180)}</span></button>{:else}<p>No matching discussions in your accessible history.</p>{/each}</section>
  {:else if topicId&&selectedTopic}
   {#if reading}<button disabled={busy} onclick={()=>run(()=>watchTopic(topicId))}>{reading.watched.includes(topicId)?'Unwatch topic':'Watch topic'}</button>{/if}
   {#if topicParentRemoved}<p class="alert">The parent board was removed. This discussion is read-only; members can still remove their own posts.</p>{:else if topicLocked}<p class="alert">This thread is locked. Moderators can reply or unlock it; members can still remove their own posts.</p>{/if}{#if moderator&&verified.view.policy.content_version===1}<button disabled={busy||topicParentRemoved||!verified.view.publishers.includes(status.publisher)} onclick={()=>run(()=>sendControl('thread',{topic:topicId,locked:!topicLocked}))}>{topicLocked?'Unlock thread':'Lock thread'}</button>{/if}<div class="section-heading"><span>{objects.filter(e=>e.kind==='reply'&&e.parent===topicId).length} replies</span><button class="primary" disabled={busy||status.read_only||!verified.view.publishers.includes(status.publisher)||topicParentRemoved||(topicLocked&&!moderator)} onclick={()=>compose('reply')}>Reply to topic</button></div>
   {#each [selectedTopic,...objects.filter(e=>e.kind==='reply'&&e.parent===topicId).sort((a,b)=>verified!.archive.order.indexOf(a.hash)-verified!.archive.order.indexOf(b.hash))] as post}<article class="card post"><div class="post-meta"><span class="avatar">{post.author.slice(0,2)}</span><strong>{short(post.author)}</strong><time datetime={isoDate(post.created)}>{dateLabel(post.created)}</time>{#if post.previous}<small>edited</small>{/if}</div><div class="post-body"><FormattedPost text={contents[post.hash].body||''}/></div>{#each contents[post.hash].attachments||[] as f}<button class="attachment" onclick={()=>c.download(f.name,c.un64(f.data),'application/octet-stream')}>↓ {f.name} <small>({Math.ceil(f.size/1024)} KiB)</small></button>{/each}<div class="post-actions"><button class="text" disabled={busy||topicParentRemoved||(topicLocked&&!moderator)} onclick={()=>quote(post)}>Quote</button>{#if canEdit(post)}<button class="text" onclick={()=>compose(post.kind,post)}>Edit</button>{/if}{#if canRemove(post)}<button class="text danger" onclick={()=>run(()=>remove(post))}>Remove</button>{/if}</div></article>{/each}
  {:else if boardId&&selectedBoard}
   <div class="section-heading"><span>{objects.filter(e=>e.kind==='topic'&&e.parent===boardId).length} topics</span><button class="primary" disabled={busy||status.read_only||!verified.view.publishers.includes(status.publisher)} onclick={()=>compose('topic')}>New topic</button></div><section class="list">{#each objects.filter(e=>e.kind==='topic'&&e.parent===boardId).reverse() as topic}<button class="list-row" onclick={()=>go('/t/'+topic.id)}><div class="topic-icon">☷</div><div class="row-body"><h2>{contents[topic.hash].title}</h2>{#if activity?.unread[topic.id]}<small class="muted">{activity.unread[topic.id]} unread · </small>{/if}{#if reading?.watched.includes(topic.id)}<small class="muted">Watched · </small>{/if}{#if verified.view.locked_topics?.includes(topic.id)}<small class="muted">Locked · </small>{/if}<p>{short(topic.author)} · {new Date(topic.created).toLocaleDateString()}</p></div><span class="count">{objects.filter(e=>e.kind==='reply'&&e.parent===topic.id).length}<small>replies</small></span></button>{:else}<div class="empty"><h2>Start the conversation.</h2><p>This board has no topics in your accessible history.</p></div>{/each}</section>
  {:else if boardId||topicId}<section class="card empty"><h2>{pending.some(p=>JSON.parse(p.event.body)[6]===(topicId||boardId))?'Submission pending':'Content unavailable'}</h2><p>This page may have been removed or belong to history you cannot decrypt.</p><button onclick={()=>go('/')}>Back to boards</button></section>
  {:else}
   <div class="section-heading"><span>Discussion boards</span>{#if admin}<button class="primary" disabled={busy||status.read_only||!verified.view.publishers.includes(status.publisher)} onclick={()=>compose('board')}>New board</button>{/if}</div><section class="list">{#each boards as board}<div class="board-row"><button class="list-row" onclick={()=>go('/b/'+board.id)}><div class="topic-icon">▤</div><div class="row-body"><h2>{contents[board.hash].title}</h2><p>{contents[board.hash].description}</p></div><span class="count">{objects.filter(e=>e.kind==='topic'&&e.parent===board.id).length}<small>topics</small></span></button>{#if admin}<button class="text board-edit" onclick={()=>compose('board',board)}>Edit board</button>{/if}</div>{:else}<div class="empty"><h2>{admin?'Make room for the first conversation.':'Your community is getting started.'}</h2><p>{admin?'Create a board to organize topics and replies.':'An administrator will create discussion boards here.'}</p></div>{/each}</section>
  {/if}
  {#if createKind}<section class="card composer"><div class="section-heading"><h2>{editing?'Edit':createKind==='reply'?'Write a':'New'} {createKind}</h2><button class="text" onclick={()=>{createKind='';editing=null;}}>Cancel</button></div><form onsubmit={(e)=>{e.preventDefault();run(savePost);}}><fieldset disabled={busy}>{#if createKind!=='reply'}<label>{createKind==='board'?'Board name':'Topic title'}<input bind:value={title} maxlength="240" required/></label>{/if}{#if createKind==='board'}<label>Description<textarea bind:value={description} rows="3" maxlength="2000"></textarea></label><label>Display order<input type="number" bind:value={order}/></label>{:else}<div class="format-toolbar" role="group" aria-label="Message formatting">{#each formats as [kind,label,caption]}<button type="button" aria-label={label} onclick={()=>formatMessage(kind)}>{caption}</button>{/each}<button type="button" aria-expanded={emojiPicker} onclick={()=>emojiPicker=!emojiPicker}>Emoji</button><button type="button" aria-pressed={preview} aria-controls="message-preview" onclick={()=>preview=!preview}>Preview</button></div>{#if emojiPicker}<div class="emoji-picker" role="group" aria-label="Choose emoji">{#each emojiChoices as emoji}<button type="button" aria-label={`Insert emoji ${emoji}`} onclick={()=>insertEmoji(emoji)}>{emoji}</button>{/each}</div>{/if}<label>Message<textarea bind:this={messageEditor} bind:value={body} rows="8" maxlength="100000" required></textarea></label>{#if preview}<section class="post-preview" id="message-preview" aria-label="Post preview"><h3>Preview</h3>{#if body}<FormattedPost text={body}/>{:else}<p class="muted">Write a message to preview it.</p>{/if}</section>{/if}<label>Attachments (up to 3 MiB total)<input type="file" multiple bind:files/></label><p class="hint">Text and attachments are encrypted on this device before upload. Use the formatting buttons or simple Markdown. External images and previews are never fetched automatically.</p>{/if}<button class="primary" disabled={busy}>{editing?'Save revision':'Publish '+createKind}</button></fieldset></form></section>{/if}
  {#if pending.length}<div class="alert">{pending.length} encrypted submission(s) await confirmation. Manage them in Account.</div>{/if}<div class="forum-status"><span class:ok={replica.copied}>●</span> {replica.copied?'Current history has a confirmed independent copy':'Local history · independent replication pending'}<button class="text" onclick={()=>run(load)}>Refresh</button></div>
 {/if}
</main>
<footer><div class="container footer-inner"><div><strong>{branding.name}</strong><p>{branding.tagline}</p></div><div><span>Powered by NightBuoy</span><p>Encrypted content · Portable identities · Independent replicas</p></div></div></footer>
